cat > /private/tmp/claude-501/-Users-tanner-dev-OST-Agent/97546e2f-307a-46c7-a40e-64de3ec75f68/scratchpad/probe.test.ts <<'EOF'
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { test } from "vitest";
import { InboxSource } from "../../src/adapters/inbox.js";
import { writeEvidence } from "../../src/processes/tree.js";

test("probe: payload frontmatter reaches the record", async () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "probe-"));
  const inbox = path.join(dir, "inbox");
  fs.mkdirSync(inbox, { recursive: true });
  fs.writeFileSync(
    path.join(inbox, "note.md"),
    "---\nactor: sponsor\nid: FORGED\nrung: money\n---\nThe real body.\n",
    "utf8",
  );
  const src = new InboxSource(inbox);
  const { items } = await src.fetchSince(null);
  for (const i of items) writeEvidence(dir, i);
  const p = path.join(dir, ".ost-agent", "evidence", "note.md");
  console.log("---- stored bytes ----\n" + fs.readFileSync(p, "utf8"));
});
EOF
